import { type } from "arktype";

const add = type.fn("number", "number", ":", "number")((a, b) => a + b);
const subtract = type.fn("number", "number", ":", "number")((a, b) => a - b);
const multiply = type.fn("number", "number", ":", "number")((a, b) => a * b);
const divide = type.fn("number", "number > 0 | number < 0", ":", "number")((a, b) => a / b);
const modulo = type.fn("number", "number.integer & (number > 0 | number < 0)", ":", "number")((a, b) => a % b);

const compute = type.fn(
  "'add' | 'subtract' | 'multiply' | 'divide' | 'modulo'",
  "number",
  "number",
  ":",
  "number"
)((op, a, b) => {
  switch (op) {
    case "add": return add(a, b);
    case "subtract": return subtract(a, b);
    case "multiply": return multiply(a, b);
    case "divide": return divide(a, b);
    case "modulo": return modulo(a, b);
  }
});

try {
  console.log("compute('divide', 4, 2) =", compute("divide", 4, 2));
  console.log("compute('divide', 4, 0) =", compute("divide", 4, 0));
} catch (e: any) {
  console.log("Caught error class:", e.constructor.name);
  console.log("Caught error message:", e.message);
}

import { type } from "arktype";

export const add = type.fn("number", "number", ":", "number")(
  (a, b) => a + b
);

export const subtract = type.fn("number", "number", ":", "number")(
  (a, b) => a - b
);

export const multiply = type.fn("number", "number", ":", "number")(
  (a, b) => a * b
);

export const divide = type.fn("number", "number > 0 | number < 0", ":", "number")(
  (a, b) => a / b
);

export const modulo = type.fn(
  "number",
  "number.integer & (number > 0 | number < 0)",
  ":",
  "number"
)((a, b) => a % b);

export const compute = type.fn(
  "'add' | 'subtract' | 'multiply' | 'divide' | 'modulo'",
  "number",
  "number",
  ":",
  "number"
)((op, a, b) => {
  switch (op) {
    case "add":
      return add(a, b);
    case "subtract":
      return subtract(a, b);
    case "multiply":
      return multiply(a, b);
    case "divide":
      return divide(a, b);
    case "modulo":
      return modulo(a, b);
  }
});

import { compute } from "./src/calculator.js";

function run(op: any, a: any, b: any) {
  try {
    const res = compute(op, a, b);
    console.log(`OK ${res}`);
  } catch (e: any) {
    console.log(`ERR ${e.message}`);
  }
}

console.log("--- Valid add ---");
run("add", 1, 2);

console.log("--- Missing op ---");
run(undefined, 1, 2);

console.log("--- Missing a ---");
run("add", undefined, 2);

console.log("--- Division by zero ---");
run("divide", 4, 0);

console.log("--- Modulo by zero ---");
run("modulo", 5, 0);

console.log("--- Modulo by float ---");
run("modulo", 5, 1.5);

